samples.before:
import { Effect } from "effect"
type Operations = {
  diff: (input: { id: string }) => Effect.Effect<{ action: "replace" } | undefined>
  reconcile: (input: { id: string }) => Effect.Effect<{ name: string }, never, never>
}
declare function provider(operations: Operations): void
export const live = provider({
  diff: Effect.fn(function* ({ id }) {
    if (id === "") return undefined
    return { action: "replace" as const }
  }),
  reconcile: Effect.fn(function* ({ id }) {
    const name = yield* Effect.succeed(id)
    return { name }
  }),
})

